from pathlib import Path
import re
p=Path('neoncr/index.html')
s=p.read_text()
s=s.replace('v0.5.1','v0.6.0')

s=re.sub(r"const C=\{.*?\},L=\{.*?\};\nconst nodeInfo=\{.*?\};\nconst cannonDefs=",'''const C={right:'#67f8ff',left:'#ff4fd8',split2:'#ffe35c',split4:'#82ff71',grow:'#aa7cff',radial:'#ff9a52',link:'#efffff',spawn:'#ffffff',spawn6:'#dffcff',spawn8:'#b8efff',spawn12:'#8ee8ff',armor2:'#58d5ff',armor3:'#ff7088',beamH:'#ffd84a',beamV:'#72ffeb',armor4:'#ff9f43',armor5:'#ff3f63',mover:'#7dff9b'},L={right:'→',left:'←',split2:'◇',split4:'✣',grow:'◉',radial:'✺',link:'⌁',spawn:'+4',spawn6:'+6',spawn8:'+8',spawn12:'+12',armor2:'Ⅱ',armor3:'Ⅲ',beamH:'━',beamV:'┃',armor4:'Ⅳ',armor5:'Ⅴ',mover:'↻'};
const nodeInfo={right:{name:'IMPULSO DERECHA',desc:'Dispara un pulso hacia la derecha.',unlock:1},left:{name:'IMPULSO IZQUIERDA',desc:'Dispara un pulso hacia la izquierda.',unlock:1},split2:{name:'BIFURCADOR',desc:'Se divide en dos pulsos diagonales.',unlock:3},grow:{name:'ONDA EXPANSIVA',desc:'Genera un círculo que activa nodos cercanos.',unlock:8},split4:{name:'CRUCETA',desc:'Dispara cuatro pulsos en cruz.',unlock:15},radial:{name:'RADIAL',desc:'Explota en ocho direcciones.',unlock:25},link:{name:'ENLACE',desc:'Activa los tres nodos vivos más cercanos.',unlock:38},beamH:{name:'BARRIDO H',desc:'Lanza una barra horizontal que destruye a su paso.',unlock:55},beamV:{name:'BARRIDO V',desc:'Lanza una barra vertical que destruye a su paso.',unlock:75},armor2:{name:'BLINDADO II',desc:'Resiste 2 impactos. Aparece automáticamente.',unlock:10},spawn:{name:'GENERADOR +4',desc:'Al romperse crea cuatro nodos nuevos.',unlock:12},mover:{name:'ERRANTE',desc:'Nodo pequeño y veloz. Es difícil acertarle.',unlock:20},armor3:{name:'BLINDADO III',desc:'Resiste 3 impactos. Aparece automáticamente.',unlock:24},spawn6:{name:'GENERADOR +6',desc:'Al romperse crea seis nodos nuevos.',unlock:30},armor4:{name:'BLINDADO IV',desc:'Resiste 4 impactos y exige más penetración.',unlock:40},spawn8:{name:'GENERADOR +8',desc:'Al romperse crea ocho nodos nuevos.',unlock:48},armor5:{name:'BLINDADO V',desc:'Resiste 5 impactos. Blindaje extremo.',unlock:58},spawn12:{name:'GENERADOR +12',desc:'Al romperse crea doce nodos nuevos.',unlock:68}};
const nodeUnlocks=[{type:'split2',sector:3,cost:300},{type:'grow',sector:8,cost:1400},{type:'split4',sector:15,cost:4200},{type:'radial',sector:25,cost:10000},{type:'link',sector:38,cost:22000},{type:'beamH',sector:55,cost:40000},{type:'beamV',sector:75,cost:60000}];
const worldTypes=new Set(['armor2','armor3','armor4','armor5','spawn','spawn6','spawn8','spawn12','mover']);
const generatorTypes=new Set(['spawn','spawn6','spawn8','spawn12']);
const cannonDefs=''',s,count=1,flags=re.S)

anchor="seen:new Set(['right','left'])};"
if anchor not in s: raise SystemExit('state anchor missing')
s=s.replace(anchor,"seen:new Set(['right','left']),unlockedNodes:new Set(['right','left'])};",1)

s=re.sub(r"function availableTypes\(\)\{.*?\}function lateScale","function availableTypes(){return Object.keys(nodeInfo).filter(k=>state.unlockedNodes.has(k)||(worldTypes.has(k)&&state.sector>=nodeInfo[k].unlock))}function lateScale",s,count=1,flags=re.S)
s=s.replace("am=isArmored(type)?1.18+hp*.22:1,scale=","am=isArmored(type)?1.18+hp*.22:type==='mover'?.72:1,scale=",1)
s=re.sub(r"function newUnlockForSector\(\)\{.*?\}function showNodeIntro","function newUnlockForSector(){return Object.entries(nodeInfo).find(([k,v])=>worldTypes.has(k)&&v.unlock===state.sector&&!state.seen.has(k))?.[0]||null}function showNodeIntro",s,count=1,flags=re.S)

s=re.sub(r"function spawnFour\(source\)\{.*?\}\nfunction trigger",'''function spawnMore(source,count){let pool=availableTypes().filter(k=>!generatorTypes.has(k)&&!isArmored(k));if(!pool.length)pool=['right','left'];for(let i=0;i<count;i++){let pos=freeSpot(),type=pool[(Math.random()*pool.length)|0];addNode(pos.x,pos.y,type,rand(10.5,14.2));state.beams.push({x1:source.x,y1:source.y,x2:pos.x,y2:pos.y,color:'#fff',life:0,max:.32});burst(pos.x,pos.y,'#fff',10,120)}state.goal+=count;tone(220,.07,'triangle',.02);tone(330,.07,'triangle',.014,.04);tone(520,.09,'triangle',.011,.08);updateUI()}
function trigger''',s,count=1,flags=re.S)
s=s.replace("if(n.type==='spawn')spawnFour(n);if(n.type==='beamH')","if(n.type==='spawn')spawnMore(n,4);if(n.type==='spawn6')spawnMore(n,6);if(n.type==='spawn8')spawnMore(n,8);if(n.type==='spawn12')spawnMore(n,12);if(n.type==='beamH')",1)
s=s.replace("if(n.alive&&n.type==='mover'){let t=performance.now()/1000+n.movePhase;n.x=n.ox+Math.cos(t*1.45)*28*lateScale();n.y=n.oy+Math.sin(t*1.9)*18*lateScale()}","if(n.alive&&n.type==='mover'){let t=performance.now()/1000+n.movePhase;n.x=n.ox+Math.cos(t*3.35)*62*lateScale();n.y=n.oy+Math.sin(t*4.15)*38*lateScale()}",1)

old="let pool=availableTypes(),count=sectorCount();for(let i=0;i<count;i++){let pos=freeSpot(),type=pool[(Math.random()*pool.length)|0];addNode(pos.x,pos.y,type,rand(10.5,14.2))}let fresh=newUnlockForSector();"
new="let pool=availableTypes(),count=sectorCount(),ordinary=pool.filter(k=>!generatorTypes.has(k)),gens=pool.filter(k=>generatorTypes.has(k));for(let i=0;i<count;i++){let pos=freeSpot(),type=gens.length&&Math.random()<.055?gens[(Math.random()*gens.length)|0]:ordinary[(Math.random()*ordinary.length)|0];addNode(pos.x,pos.y,type,rand(10.5,14.2))}let fresh=newUnlockForSector();"
if old not in s: raise SystemExit('sector pool anchor missing')
s=s.replace(old,new,1)

pat=r"function renderShop\(\)\{.*?\}\nui\.tabCannon\.onclick"
m=re.search(pat,s,flags=re.S)
if not m: raise SystemExit('renderShop missing')
render='''function renderShop(){ui.shop.classList.toggle('cannonTab',state.shopTab==='cannon');ui.shop.classList.toggle('nodesTab',state.shopTab==='nodes');ui.shopCredits.textContent=state.credits;ui.tabCannon.classList.toggle('active',state.shopTab==='cannon');ui.tabNodes.classList.toggle('active',state.shopTab==='nodes');ui.cannonBlock.style.display=state.shopTab==='cannon'?'block':'none';ui.upgradeTitle.textContent=state.shopTab==='cannon'?'MEJORAS DE CAÑÓN':'NODOS Y MEJORAS';let cur=cannonDefs[state.cannonLevel],next=cannonDefs[state.cannonLevel+1];if(next){let sectorOk=state.sector>=next.minSector,moneyOk=state.credits>=next.cost,can=sectorOk&&moneyOk;ui.cannonUpgrade.disabled=!can;ui.cannonUpgrade.className='cannonUpgrade'+(can?' ready':'');let lock=!sectorOk?`<span class="cannonLock">SECTOR ${next.minSector}</span>`:moneyOk?'':'<span class="cannonLock">FALTAN <span class="coin tinyCoin">$</span> '+(next.cost-state.credits)+'</span>';ui.cannonUpgrade.innerHTML=`<div class="cannonCompare"><div class="cannonSide"><div class="cannonThumb">${cannonThumb(state.cannonLevel)}</div><div class="cannonLabel">${cur.name}</div></div><div class="cannonArrow">→</div><div class="cannonSide"><div class="cannonThumb">${cannonThumb(state.cannonLevel+1)}</div><div class="cannonLabel">${next.name}</div></div></div><div class="cannonMeta"><span class="cannonCost"><span class="coin">$</span> ${next.cost}</span>${lock}</div>`;ui.cannonUpgrade.onclick=()=>upgradeCannon(next)}else{ui.cannonUpgrade.disabled=true;ui.cannonUpgrade.className='cannonUpgrade';ui.cannonUpgrade.innerHTML=`<div class="cannonCompare"><div></div><div class="cannonSide"><div class="cannonThumb">${cannonThumb(state.cannonLevel)}</div><div class="cannonLabel">${cur.name}</div></div><div></div></div><div class="cannonMeta"><span class="cannonCost">MÁXIMO</span></div>`}ui.upGrid.innerHTML='';if(state.shopTab==='nodes'){let title=document.createElement('div');title.className='gridSection';title.textContent='DESBLOQUEO DE NODOS';ui.upGrid.appendChild(title);for(let d of nodeUnlocks){let inf=nodeInfo[d.type],owned=state.unlockedNodes.has(d.type),sectorOk=state.sector>=d.sector,moneyOk=state.credits>=d.cost,b=document.createElement('button');b.className='card nodeUnlockCard';b.style.color=C[d.type];b.disabled=owned||!sectorOk||!moneyOk;let label=owned?'DESBLOQUEADO':!sectorOk?'SECTOR '+d.sector:'<span class="coin tinyCoin">$</span> '+d.cost;b.innerHTML=`<div class="upgradeIcon nodeUnlockGlyph">${L[d.type]}</div><div class="ct">${inf.name}</div><div class="cc">${label}</div><div class="cd">${inf.desc}</div><div class="prog"><span class="status">${owned?'YA APARECE EN LOS SECTORES':sectorOk?'COMPRAR':'SE DESBLOQUEA MÁS ADELANTE'}</span></div>`;b.onclick=()=>{if(!state.unlockedNodes.has(d.type)&&state.sector>=d.sector&&state.credits>=d.cost){state.credits-=d.cost;state.unlockedNodes.add(d.type);tone(620,.12,'triangle',.035);tone(930,.12,'sine',.02,.06);renderShop();updateUI();setTimeout(()=>showNodeIntro(d.type),80)}};ui.upGrid.appendChild(b)}let stats=document.createElement('div');stats.className='gridSection';stats.textContent='MEJORAS DE NODOS';ui.upGrid.appendChild(stats)}for(let u of adjustments.filter(x=>x.tab===state.shopTab)){let lv=state.up[u.k],limit=u.k==='penetration'?state.cannonLevel:u.max,c=cost(u),locked=u.k==='penetration'&&limit<u.max&&lv>=limit,maxed=lv>=u.max,b=document.createElement('button');b.className='card';b.disabled=lv>=limit||state.credits<c;b.style.color=u.color;let label=maxed?'MÁXIMO':locked?'BLOQUEADO':'<span class="coin tinyCoin">$</span> '+c;b.innerHTML=`<div class="upgradeIcon">${icons[u.k]}</div><div class="ct">${u.name}</div><div class="cc">${label}</div><div class="cd">${u.desc}</div><div class="prog">${pips(lv,limit,u.max,u.color)}${locked?'<span class="status">MEJORÁ EL CAÑÓN</span>':''}</div>`;b.onclick=()=>{if(state.credits>=c&&state.up[u.k]<limit){state.credits-=c;state.up[u.k]++;tone(u.k==='penetration'?720:520,.07,'triangle',.025);renderShop();updateUI()}};ui.upGrid.appendChild(b)}}
ui.tabCannon.onclick'''
s=s[:m.start()]+render+s[m.end():]

css='''<style id="v060-node-store">.gridSection{grid-column:1/-1;text-align:center;font-size:8px;letter-spacing:.18em;color:#9fc4cc;padding:5px 0 2px;border-bottom:1px solid #67f8ff22}.nodeUnlockGlyph{font-size:22px;font-weight:1000;text-shadow:0 0 12px currentColor}#shop.nodesTab .shopContent{overflow:auto;scrollbar-width:thin}#shop.nodesTab #upgradeGrid{grid-template-columns:repeat(3,minmax(0,1fr));padding-right:2px}#shop.nodesTab .nodeUnlockCard .cc{font-size:8px}@media(max-width:700px){#shop.nodesTab #upgradeGrid{grid-template-columns:repeat(2,minmax(0,1fr))}#shop.nodesTab .card{min-height:62px;padding:4px 6px;grid-template-columns:33px minmax(0,1fr) auto;gap:1px 5px}#shop.nodesTab .upgradeIcon{width:33px;height:33px}.nodeUnlockGlyph{font-size:18px}}</style>'''
s=s.replace('</head>',css+'</head>',1)
p.write_text(s)
